<?php require_once __DIR__."/../config/auth.php";require_role(["admin","warehouse"]);$pdo=db();if($_SERVER["REQUEST_METHOD"]==="POST"){try{check_csrf($_POST["csrf"]??"");$s=$pdo->prepare("INSERT INTO products(sku,barcode,name_ar,name_en,purchase_price,sale_price,stock_qty,min_stock) VALUES(?,?,?,?,?,?,?,?)");$s->execute([trim($_POST["sku"]),trim($_POST["barcode"])?:null,trim($_POST["name_ar"]),trim($_POST["name_en"]),(float)$_POST["buy"],(float)$_POST["sale"],(float)$_POST["stock"],(float)$_POST["min"]]);$_SESSION["flash"]=["type"=>"ok","msg"=>"Product added."];}catch(Throwable $e){$_SESSION["flash"]=["type"=>"bad","msg"=>$e->getMessage()];}redirect("products.php");}$rows=$pdo->query("SELECT * FROM products WHERE is_active=1 ORDER BY id DESC")->fetchAll();include __DIR__."/partials/header.php";?><header><h1><?=t("المنتجات","Products")?></h1></header><div class="card"><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="name_ar" placeholder="الاسم عربي" required><input name="name_en" placeholder="English name" required><input name="sku" placeholder="SKU" required><input name="barcode" placeholder="Barcode"><input name="buy" type="number" step=".01" placeholder="Purchase"><input name="sale" type="number" step=".01" placeholder="Sale"><input name="stock" type="number" step=".001" placeholder="Stock"><input name="min" type="number" step=".001" value="5" placeholder="Min stock"><button class="btn primary">Save</button></form></div><div class="card"><table><tr><th>SKU</th><th>Name</th><th>Sale</th><th>Stock</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r["sku"])?></td><td><?=e($r["name_en"])?></td><td><?=number_format($r["sale_price"],2)?></td><td><?=$r["stock_qty"]?></td><td><?=$r["stock_qty"]<=$r["min_stock"]?"LOW":"OK"?></td></tr><?php endforeach;?></table></div><?php include __DIR__."/partials/footer.php";?>